def lora_state_hash(state: Mapping[str, torch.Tensor]) -> str:
    digest = hashlib.sha256()
    for name, tensor in state.items():
        digest.update(name.encode("utf-8"))
        cpu = tensor.detach().to(device="cpu", dtype=torch.float32).contiguous()
